const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const chiangMai = ee.Geometry.Point(98.9898, 18.7883); // Approximate coordinates for Chiang Mai, Thailand

  const startMarch2024 = '2024-03-01';
  const endMarch2024 = '2024-03-31';
  const startMay2024 = '2024-05-01';
  const endMay2024 = '2024-05-31';

  const bandName = 'AOD_550'; // Aerosol Optical Depth at 550nm
  const qaBand = 'qa_value'; // Quality assurance value

  // 2. Data Acquisition & Check
  const s5pAod = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_AOD')
    .select([bandName, qaBand]);

  // Filter for March 2024
  let collectionMarch = s5pAod
    .filterDate(startMarch2024, endMarch2024)
    .filterBounds(chiangMai)
    .filter(ee.Filter.gt(qaBand, 0.75)); // Filter for high quality data

  // Filter for May 2024
  let collectionMay = s5pAod
    .filterDate(startMay2024, endMay2024)
    .filterBounds(chiangMai)
    .filter(ee.Filter.gt(qaBand, 0.75)); // Filter for high quality data

  const sizeMarch = await collectionMarch.size().getInfo();
  const sizeMay = await collectionMay.size().getInfo();

  if (sizeMarch === 0 || sizeMay === 0) {
    console.log(`March 2024 Images: ${sizeMarch}`);
    console.log(`May 2024 Images: ${sizeMay}`);
    console.log('C1');
    return;
  }

  // Calculate the mean image for each period
  const meanAodMarch = collectionMarch.mean();
  const meanAodMay = collectionMay.mean();

  const scale = 1000; // Use a reasonable scale for regional averages
  const maxPixels = 1e9;

  // Function to calculate mean AOD and pixel count for a given image
  const calculateAodStats = async (image, geometry, band, periodName) => {
    const regionStats = await image.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: scale,
      maxPixels: maxPixels
    }).getInfo();

    const aodValue = regionStats[band];
    const pixelCount = regionStats[`${band}_count`];

    return { aodValue, pixelCount, periodName };
  };

  const statsMarch = await calculateAodStats(meanAodMarch, chiangMai, bandName, 'March 2024');
  const statsMay = await calculateAodStats(meanAodMay, chiangMai, bandName, 'May 2024');

  // 3. Processing & 4. Calculation
  if (statsMarch.pixelCount === 0 || statsMay.pixelCount === 0) {
    console.log(`March 2024 Images: ${sizeMarch}, Pixels: ${statsMarch.pixelCount}`);
    console.log(`May 2024 Images: ${sizeMay}, Pixels: ${statsMay.pixelCount}`);
    console.log('C2');
    return;
  }

  const aodMarch = statsMarch.aodValue;
  const aodMay = statsMay.aodValue;

  if (aodMarch === null || isNaN(aodMarch) || aodMay === null || isNaN(aodMay)) {
    console.log(`March 2024 AOD: ${aodMarch}, Pixels: ${statsMarch.pixelCount}`);
    console.log(`May 2024 AOD: ${aodMay}, Pixels: ${statsMay.pixelCount}`);
    console.log('C3');
    return;
  }

  // 5. Validation & Final Answer
  console.log(`March 2024 Images: ${sizeMarch}, AOD: ${aodMarch.toFixed(4)}, Pixels: ${statsMarch.pixelCount}`);
  console.log(`May 2024 Images: ${sizeMay}, AOD: ${aodMay.toFixed(4)}, Pixels: ${statsMay.pixelCount}`);

  if (aodMarch > aodMay) {
    console.log('A'); // Yes, AOD was higher in March
  } else {
    console.log('B'); // No, AOD was not higher in March (or was equal/lower)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
